#include <bits/stdc++.h>
using namespace std;

void fft(std::vector<double>& re, std::vector<double>& im, bool inverse, const std::vector<double>& cs, const std::vector<double>& sn, const std::vector<double>& csi, const std::vector<double>& sni) {
    int n = re.size();
    int shift = 32 - (int)std::floor(std::log2(n));
    for (int i=1; i<n; i++) {
        int j = std::reverse(i << shift) >> shift;
        if (i<j) {
            std::swap(re[i], re[j]);
            std::swap(im[i], im[j]);
        }
    }

    for (int len=2; len<=n; len <<= 1) {
        int half = len>>1;
        int wIdx = (int)cs.size() / len;
        for (int i=0; i<n; i+=len) {
            for (int j=0, k=0; j<half; j++, k+=wIdx) {
                double wRe = inverse ? csi[k] : cs[k];
                double wIm = inverse ? sni[k] : sn[k];
                double uRe = re[i+j];
                double uIm = im[i+j];
                double vRe = re[i+j+half] * wRe - im[i+j+half] * wIm;
                double vIm = re[i+j+half] * wIm + im[i+j+half] * wRe;
                re[i+j] = uRe + vRe;
                im[i+j] = uIm + vIm;
                re[i+j+half] = uRe - vRe;
                im[i+j+half] = uIm - vIm;
            }
        }
    }
    if (inverse) {
        for (int i=0; i<n; i++) {
            re[i] /= n;
            im[i] /= n;
        }
    }
}

std::vector<int> multiplyMod(const std::vector<int>& a, const std::vector<int>& b, int m, const std::vector<double>& cs, const std::vector<double>& sn, const std::vector<double>& csi, const std::vector<double>& sni) {
    int need = a.size() + b.size() -1;
    int n = 1 << (int)std::ceil(std::log2(need));
    std::vector<double> aRe(n,0), aIm(n,0), bRe(n,0), bIm(n,0);
    for (size_t i=0; i<a.size(); i++) {
        int x = a[i]%m;
        aRe[i] = x & ((1<<15)-1);
        aIm[i] = x >> 15;
    }
    fft(aRe, aIm, false, cs, sn, csi, sni);
    for (size_t i=0; i<b.size(); i++) {
        int x = b[i]%m;
        bRe[i] = x & ((1<<15)-1);
        bIm[i] = x >> 15;
    }
    fft(bRe, bIm, false, cs, sn, csi, sni);
    std::vector<double> aRe2(n,0), aIm2(n,0), bRe2(n,0), bIm2(n,0);
    for (int i=0; i<n; i++) {
        int j = (n - i) & (n -1);
        double a1r = (aRe[i] + aRe[j]) / 2.0;
        double a1i = (aIm[i] - aIm[j]) / 2.0;
        double a2r = (aIm[i] + aIm[j]) / 2.0;
        double a2i = (aRe[j] - aRe[i]) / 2.0;
        double b1r = (bRe[i] + bRe[j]) / 2.0;
        double b1i = (bIm[i] - bIm[j]) / 2.0;
        double b2r = (bIm[i] + bIm[j]) / 2.0;
        double b2i = (bRe[j] - bRe[i]) / 2.0;
        aRe2[i] = a1r * b1r - a1i * b1i - a2r * b2i - a2i * b2r;
        aIm2[i] = a1r * b1i + a1i * b1r + a2r * b2r - a2i * b2i;
        bRe2[i] = a1r * b2r - a1i * b2i + a2r * b1r - a2i * b1i;
        bIm2[i] = a1r * b2i + a1i * b2r + a2r * b1i + a2i * b1r;
    }
    fft(aRe2, aIm2, true, cs, sn, csi, sni);
    fft(bRe2, bIm2, true, cs, sn, csi, sni);
    std::vector<int> res(need,0);
    for (int i=0; i<need; i++) {
        long long aa = std::llround(aRe2[i]);
        long long bb = std::llround(bRe2[i]);
        long long cc = std::llround(aIm2[i]);
        res[i] = (int)((aa + (bb << 15) + (cc <<30)) % m);
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int mod = 998244353;
    int n, k;
    cin >> n >> k;
    std::vector<int> v(10,0);
    for (int i=0; i<k; i++) {
        int x;
        cin >> x;
        v[x] = 1;
    }
    std::vector<int> ans = {1};
    int p = n/2;

    // Precompute roots for FFT
    int maxLen = 1 << (int)std::ceil(std::log2(n+1));
    std::vector<double> cs(maxLen/2), sn(maxLen/2), csi(maxLen/2), sni(maxLen/2);
    for (int i=0; i<maxLen/2; i++) {
        double angle = 2 * M_PI * i / maxLen;
        cs[i] = cos(angle);
        sn[i] = sin(angle);
        csi[i] = cos(-angle);
        sni[i] = sin(-angle);
    }

    while (p > 0) {
        if (p & 1) {
            ans = multiplyMod(ans, v, mod, cs, sn, csi, sni);
        }
        v = multiplyMod(v, v, mod, cs, sn, csi, sni);
        p >>=1;
    }
    long long result = 0;
    for (int x : ans) {
        long long val = (long long)x * x % mod;
        result = (result + val) % mod;
    }
    cout << result << "\n";
    return 0;
}

